#!/usr/bin/env python3
"""Ingest routes from the tools API → util/autogenerated/routes.py.

The new schema is:
    {id, name, locations[2], distance, options[]: [{
        options: {<location>: bool},
        terrainModifiers: [<terrain_modifier_id>]
    }]}

Compared to the old wiki-scraped shape:
    (Location.A, Location.B): {distance, agility_level?, keyword_counts?}

Two real schema changes:
  1. distanceModifier was REMOVED. The new `distance` value already has
     any modifier baked in (verified: old 1000*1.08 ≈ new 1080). No
     separate modifier field is published.
  2. Per-route requirements moved into terrain_modifiers, referenced by
     id. We cross-reference /terrain_modifiers/ to recover the keyword
     counts and skill-level requirements in a shape similar to the
     legacy file.

Output keeps the raw API shape AND a derived `requirements` dict per
direction (for both A→B and B→A). Consumers can use whichever they need.
"""
from __future__ import annotations
import re
import sys
from pathlib import Path
from typing import Any, Dict, List

sys.path.insert(0, str(Path(__file__).resolve().parent.parent.parent))
from util.scrapers.tools_api_client import ToolsAPIClient  # noqa: E402
from util.scrapers.tools_api_transform import write_python_data_module  # noqa: E402


def _terrain_to_requirements(tm: Dict[str, Any]) -> Dict[str, Any]:
    """Convert a terrain_modifier detail into {keyword_counts, skill}."""
    out: Dict[str, Any] = {'keyword_counts': {}, 'skill': {}}
    for req in tm.get('requirements', []) or []:
        rtype = req.get('type')
        body = req.get('requirement') or {}
        if rtype == 'distinctKeywordItemsEquipped':
            qty = int(body.get('quantity', 0))
            for kw in body.get('keywords', []) or []:
                # match the legacy file's "diving gear" not "diving_gear"
                out['keyword_counts'][kw.replace('_', ' ')] = qty
        elif rtype == 'skillLevel':
            skill = (body.get('skill') or '').lower()
            level = int(body.get('level', 0))
            if skill:
                out['skill'][skill] = level
    return out


def _build_route_entry(
    route: Dict[str, Any],
    terrain_index: Dict[str, Dict[str, Any]],
) -> Dict[str, Any]:
    locations = route.get('locations') or []
    options = route.get('options') or []

    # Direction-aware: each option declares which endpoint(s) it applies to.
    # For each direction, union the requirements from applicable options.
    derived: Dict[str, Dict[str, Any]] = {}
    for loc_id in locations:
        per_dir: Dict[str, Any] = {'keyword_counts': {}, 'skill': {}}
        for opt in options:
            applies_to = opt.get('options') or {}
            if not applies_to.get(loc_id, False):
                continue
            for tm_id in opt.get('terrainModifiers', []) or []:
                tm = terrain_index.get(tm_id)
                if not tm:
                    continue
                tm_reqs = _terrain_to_requirements(tm)
                for kw, qty in tm_reqs['keyword_counts'].items():
                    # take the max if multiple modifiers ask for the same keyword
                    cur = per_dir['keyword_counts'].get(kw, 0)
                    per_dir['keyword_counts'][kw] = max(cur, qty)
                for skl, lvl in tm_reqs['skill'].items():
                    cur = per_dir['skill'].get(skl, 0)
                    per_dir['skill'][skl] = max(cur, lvl)
        derived[loc_id] = per_dir

    return {
        'id': route['id'],
        'name': route.get('name'),
        'locations': locations,
        'distance': route.get('distance'),
        # Raw API options[] preserved verbatim (terrain modifier cross-ref):
        'options': options,
        # Derived per-direction requirements (legacy-shape parity helper):
        'requirements_by_endpoint': derived,
    }


def run(client: ToolsAPIClient, *, use_cache: bool = True) -> int:
    routes = client.list('routes', use_cache=use_cache)
    # Fetch all terrain modifiers once (small set) for cross-reference.
    tm_list = client.list('terrain_modifiers', use_cache=use_cache)
    terrain_index = {
        t['id']: client.get('terrain_modifiers', t['id'], use_cache=use_cache)
        for t in tm_list if t.get('id')
    }

    data = {r['id']: _build_route_entry(r, terrain_index) for r in routes if r.get('id')}

    out = (
        Path(__file__).resolve().parent.parent
        / 'autogenerated' / 'routes.py'
    )
    write_python_data_module(
        str(out), 'ROUTES', data,
        docstring=(
            'Routes — keyed by route slug-id (e.g. "barbantok-to-casbrant_fields").\n\n'
            'API schema change: distanceModifier was removed; distance is '
            'already post-modifier. Requirements moved into terrain_modifiers '
            "via options[]. We resolve them here into requirements_by_endpoint "
            "for legacy-shape parity, while preserving the raw options[] array."
        ),
    )
    print(f'  [routes             ] {len(data):4d} entities → routes.py')
    return len(data)


if __name__ == '__main__':
    raise SystemExit(0 if run(ToolsAPIClient()) else 1)
